<script setup>
import { computed, reactive, ref } from 'vue'
import AppModal from '@/components/ui/AppModal.vue'
import { useEvents } from '@/composables/useEvents'
const { activeEvents, completedEvents, createEvent, completeEvent, deleteEvent } = useEvents()
const currentTab = ref('active')
const form = reactive({ title: '', category: '', date: '', location: '', price: '', desc: '' })
const errorMessage = ref(''), successMessage = ref(''), modalAction = ref(null), selectedEvent = ref(null)
const tabs = computed(() => [{ id: 'active', label: 'Active Events', count: activeEvents.value.length }, { id: 'create', label: 'Create Event' }, { id: 'completed', label: 'Completed Events', count: completedEvents.value.length }])
function formatDate(value) { if (!value) return 'Date not set'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('en', { dateStyle: 'medium', timeStyle: 'short' }).format(date) }
function submitEvent() { errorMessage.value = ''; successMessage.value = ''; if (['title','category','date','location','desc'].some((key) => !String(form[key]).trim())) { errorMessage.value = 'Please fill in every required field before publishing.'; return } createEvent({ ...form }); Object.assign(form, { title:'', category:'', date:'', location:'', price:'', desc:'' }); currentTab.value = 'active'; successMessage.value = 'Your event has been published and added to the public catalog.' }
function askAction(action, event) { modalAction.value = action; selectedEvent.value = event }
function closeModal() { modalAction.value = null; selectedEvent.value = null }
function confirmAction() { if (!selectedEvent.value) return; if (modalAction.value === 'complete') completeEvent(selectedEvent.value.id); if (modalAction.value === 'delete') deleteEvent(selectedEvent.value.id); closeModal() }
const modalTitle = computed(() => modalAction.value === 'complete' ? 'Complete this event?' : 'Delete this event?')
const modalMessage = computed(() => modalAction.value === 'complete' ? `?${selectedEvent.value?.title}? will move to Completed Events and leave the public catalog.` : `?${selectedEvent.value?.title}? will be permanently removed from your event list.`)
</script>
<template>
<div class="management-page"><div class="page-heading"><div><span class="eyebrow">EVENT WORKSPACE</span><h2>Manage your events</h2><p>Create listings, update their status, and review completed events.</p></div><span class="workspace-count">{{ activeEvents.length }} active</span></div>
<div v-if="successMessage" class="feedback success" role="status"><span>?</span>{{ successMessage }}<button type="button" aria-label="Dismiss" @click="successMessage = ''">?</button></div>
<div class="tabs" role="tablist" aria-label="Event management sections"><button v-for="tab in tabs" :key="tab.id" type="button" role="tab" :aria-selected="currentTab === tab.id" :class="{selected:currentTab===tab.id}" @click="currentTab=tab.id; errorMessage=''; successMessage=''">{{ tab.label }}<span v-if="tab.count !== undefined" class="tab-count">{{ tab.count }}</span></button></div>
<section v-if="currentTab==='active'" class="tab-panel" role="tabpanel"><div class="section-heading"><div><h3>Active Events</h3><p>These listings are visible to participants.</p></div><button class="small-primary" type="button" @click="currentTab='create'">? Create event</button></div><div v-if="activeEvents.length" class="event-grid"><article v-for="event in activeEvents" :key="event.id" class="event-card"><div class="card-top"><span class="category-pill">{{ event.category }}</span><span class="status-pill">Active</span></div><h4>{{ event.title }}</h4><div class="event-meta"><span>? {{ formatDate(event.date) }}</span><span>? {{ event.location }}</span></div><p class="event-description">{{ event.desc }}</p><div class="card-bottom"><strong>{{ event.price || 'Free' }}</strong><div><button class="action-button complete-button" type="button" @click="askAction('complete',event)">Complete event</button><button class="action-button delete-button" type="button" @click="askAction('delete',event)">Delete</button></div></div></article></div><div v-else class="empty-state"><span class="empty-art">?</span><h3>No active events yet</h3><p>Your event cards will appear here after you publish one.</p><button class="small-primary" type="button" @click="currentTab='create'">Create your first event</button></div></section>
<section v-else-if="currentTab==='create'" class="tab-panel form-panel" role="tabpanel"><div class="section-heading"><div><h3>Create a new event</h3><p>Share the key details so people know what to expect.</p></div></div><form class="event-form" novalidate @submit.prevent="submitEvent"><div v-if="errorMessage" class="feedback error" role="alert"><span>!</span>{{ errorMessage }}</div><label>Event title <span>*</span><input v-model="form.title" type="text" placeholder="e.g. Creative Community Meetup" maxlength="90" required></label><div class="form-row"><label>Category <span>*</span><select v-model="form.category" required><option value="" disabled>Select a category</option><option>Community</option><option>Technology</option><option>Music &amp; Concerts</option><option>Art &amp; Design</option><option>Business</option><option>Health &amp; Wellness</option><option>Food &amp; Drink</option><option>Education</option><option>Other</option></select></label><label>Date and time <span>*</span><input v-model="form.date" type="datetime-local" required></label></div><label>Location <span>*</span><input v-model="form.location" type="text" placeholder="Venue or online location" maxlength="120" required></label><div class="form-row"><label>Ticket price<input v-model="form.price" type="text" placeholder="Free or e.g. Rp 50.000"></label><label>Description <span>*</span><textarea v-model="form.desc" rows="4" placeholder="What will participants experience?" maxlength="600" required></textarea></label></div><div class="form-actions"><span>Fields marked * are required.</span><button class="small-primary" type="submit">Publish event ?</button></div></form></section>
<section v-else class="tab-panel" role="tabpanel"><div class="section-heading"><div><h3>Completed Events</h3><p>Finished events are kept here for reference.</p></div></div><div v-if="completedEvents.length" class="completed-list"><article v-for="event in completedEvents" :key="event.id" class="completed-card"><div><span class="category-pill">{{ event.category }}</span><h4>{{ event.title }}</h4><p>{{ formatDate(event.date) }} ? {{ event.location }}</p></div><span class="status-pill archived">? Completed</span></article></div><div v-else class="empty-state"><span class="empty-art muted">?</span><h3>No completed events</h3><p>When you complete an active event, it will be archived here.</p></div></section></div>
<AppModal :isopen="Boolean(modalAction)" :title="modalTitle" :message="modalMessage" :confirm-text="modalAction==='complete'?'Complete event':'Delete event'" @confirm="confirmAction" @close="closeModal" />
</template>
<style scoped>
