:0;color:inherit;background:transparent;font-size:1.2rem;cursor:pointer}.empty-state{display:grid;justify-items:center;gap:.5rem;padding:3rem 1rem;text-align:center}.empty-art{display:grid;place-items:center;width:54px;height:54px;border-radius:18px;color:#6748ed;background:#f0edff;font-size:1.35rem}.empty-art.muted{color:#88879a;background:#f0f0f4}.empty-state h3{margin:.35rem 0 0;font-size:1rem}.empty-state p{margin:0 0 .6rem;color:#9291a3;font-size:.8rem}.completed-list{display:grid;gap:.7rem}.completed-card{display:flex;justify-content:space-between;align-items:center;gap:1rem;padding:1rem;border:1px solid #eeedf4;border-radius:13px}.completed-card h4{margin:.5rem 0 .25rem}.completed-card p{margin:0;color:#9291a3;font-size:.75rem}.status-pill.archived{color:#77768a;background:#f0f0f4}@media(max-width:700px){.page-heading,.section-heading{align-items:flex-start;flex-direction:column}.form-row{grid-template-columns:1fr}.tab-panel{padding:1rem}.completed-card,.form-actions{align-items:flex-start;flex-direction:column}}
</style>
